-- 20261114 老人预约申请沟通台账入库（林口县）
-- 来源：《林口县老人预约申请沟通台账最新.xlsx》Sheet1（第1行标题、第2行表头、第3行起数据，共 487 行）
--   原文件已不在 C:\Projects；数据取自其等同导出 CSV，已用原 Excel 的全量统计指标逐项反验一致。
--   1) 建表 nc_biz_elderly_appointment_ledger（Schema 权威定义见
--      Resources\Schema\elderly_appointment_ledger\database.yaml，两处结构必须一致）
--   2) 灌入 487 行：id_card 唯一键，ON CONFLICT 幂等 upsert（重复执行只刷新，不产生重复行）
-- 幂等：可重复执行；含数据操作（INSERT），check_migrations 归人工审阅档。
-- 校验：末尾 DO 块断言行数 = 487，不符即抛错回滚。

BEGIN;

CREATE TABLE IF NOT EXISTS nc_biz_elderly_appointment_ledger (
    id                   BIGSERIAL PRIMARY KEY,
    seq_no               INT,
    city_name            VARCHAR(100),
    county_name          VARCHAR(100),
    elder_name           VARCHAR(50)  NOT NULL,
    id_card              VARCHAR(18)  NOT NULL,
    elder_phone          VARCHAR(20),
    contact_name         VARCHAR(50),
    contact_phone        VARCHAR(20),
    service_type         VARCHAR(50),
    appointment_text     VARCHAR(50),
    appointment_date     DATE,
    appointment_half     VARCHAR(4),
    application_time_raw VARCHAR(50),
    application_time     TIMESTAMP,
    residence_address    VARCHAR(500),
    assess_result        VARCHAR(50),
    source_file          VARCHAR(200),
    source_row           INT,
    created_at           TIMESTAMP NOT NULL DEFAULT now(),
    updated_at           TIMESTAMP NOT NULL DEFAULT now(),
    deleted_at           TIMESTAMP
);

COMMENT ON TABLE nc_biz_elderly_appointment_ledger IS '[预约评估] 老人预约申请沟通台账 - 一人一行，id_card 唯一，重复导入幂等覆盖';
COMMENT ON COLUMN nc_biz_elderly_appointment_ledger.elder_name IS '老人姓名';
COMMENT ON COLUMN nc_biz_elderly_appointment_ledger.id_card IS '公民身份号码(唯一，导入幂等键)';
COMMENT ON COLUMN nc_biz_elderly_appointment_ledger.service_type IS '预约服务类型(本批全部为"能力评估")';
COMMENT ON COLUMN nc_biz_elderly_appointment_ledger.appointment_text IS '预约时间原文(如 2026-10-20 上午)';
COMMENT ON COLUMN nc_biz_elderly_appointment_ledger.appointment_date IS '预约日期(自 appointment_text 解析，统计口径)';
COMMENT ON COLUMN nc_biz_elderly_appointment_ledger.assess_result IS '评估结论/状态(源表第13列，无表头；空=尚未回填)';
COMMENT ON COLUMN nc_biz_elderly_appointment_ledger.source_file IS '来源文件名';
COMMENT ON COLUMN nc_biz_elderly_appointment_ledger.source_row IS '源表 Excel 行号(回溯核对用)';

CREATE UNIQUE INDEX IF NOT EXISTS uq_elderly_appointment_ledger_id_card
    ON nc_biz_elderly_appointment_ledger (id_card);
CREATE INDEX IF NOT EXISTS idx_elderly_appointment_ledger_date
    ON nc_biz_elderly_appointment_ledger (appointment_date);
CREATE INDEX IF NOT EXISTS idx_elderly_appointment_ledger_service
    ON nc_biz_elderly_appointment_ledger (service_type);

ON CONFLICT (id_card) DO UPDATE SET
    city_name = EXCLUDED.city_name, county_name = EXCLUDED.county_name, elder_name = EXCLUDED.elder_name, id_card = EXCLUDED.id_card, elder_phone = EXCLUDED.elder_phone, contact_name = EXCLUDED.contact_name, contact_phone = EXCLUDED.contact_phone, service_type = EXCLUDED.service_type, appointment_text = EXCLUDED.appointment_text, appointment_date = EXCLUDED.appointment_date, appointment_half = EXCLUDED.appointment_half, application_time_raw = EXCLUDED.application_time_raw, application_time = EXCLUDED.application_time, residence_address = EXCLUDED.residence_address, assess_result = EXCLUDED.assess_result, source_file = EXCLUDED.source_file, source_row = EXCLUDED.source_row, updated_at = NOW();

-- 行数断言：不符则抛错回滚
DO $$
DECLARE n int;
BEGIN
    SELECT count(*) INTO n FROM nc_biz_elderly_appointment_ledger;
    IF n <> 487 THEN
        RAISE EXCEPTION '导入行数不符：期望 487，实际 %', n;
    END IF;
    RAISE NOTICE '导入完成：nc_biz_elderly_appointment_ledger = % 行', n;
END $$;

COMMIT;
